const TIERS = ["Dean","Professor","Associate Professor","Assistant Professor","Instructional Faculty","Lecturer","Doctoral Student Faculty","Adjunct Faculty"];
const COLORS = {"Dean":"#D85A30","Professor":"#378ADD","Associate Professor":"#1D9E75","Assistant Professor":"#0F6E56","Instructional Faculty":"#7F77DD","Lecturer":"#BA7517","Doctoral Student Faculty":"#D4537E","Adjunct Faculty":"#888780"};
const REACHOUT_PRIORITY = "lee_minwoo";
document.getElementById('headerSub').textContent = PEOPLE.length + ' faculty · Research Interests · Classes Taught · Organization · Degree-Plan Course Match (note: photos omitted from this static export to keep file size small)';

const filtersEl = document.getElementById('filters');
const gridEl = document.getElementById('grid');
const countEl = document.getElementById('count');
const listViewEl = document.getElementById('listView');
const detailEl = document.getElementById('detail');
let active = 'All';

function renderList() {
  let list;
  if (active === 'All') list = PEOPLE;
  else if (active === 'Focus') list = PEOPLE.filter(p => p.is_focus);
  else if (active === 'Reachout') {
    list = PEOPLE.filter(p => p.is_reachout);
    list.sort((a, b) => (a.id === REACHOUT_PRIORITY ? -1 : b.id === REACHOUT_PRIORITY ? 1 : 0));
  }
  else if (active === 'ReachoutResearch') {
    list = PEOPLE.filter(p => p.is_research_reachout);
    list.sort((a, b) => (a.id === REACHOUT_PRIORITY ? -1 : b.id === REACHOUT_PRIORITY ? 1 : 0));
  }
  else list = PEOPLE.filter(p => p.tier === active);

  countEl.textContent = list.length + ' people';
  gridEl.innerHTML = list.map(p => `
    <div class="card ${p.is_advisor ? 'advisor' : ''} ${p.is_focus ? 'focus' : ''} ${active==='Reachout' && p.is_reachout ? 'reachout' : ''} ${active==='ReachoutResearch' && p.is_research_reachout ? 'reachout2' : ''}" onclick="openDetail('${p.id}')">
      <img src="${p.photo || 'https://placehold.co/200x244/e2e0d8/6b6a63?text=' + encodeURIComponent(p.name.split(' ')[0])}" alt="${p.name}">
      <div class="body">
        <div class="badges">
          <div class="tier-pill" style="background:${COLORS[p.tier]}">${p.tier}</div>
          ${p.is_advisor ? '<div class="advisor-pill">PhD Advisor</div>' : ''}
          ${p.is_focus ? '<div class="focus-pill">Fall 2026 - Professor</div>' : ''}
          ${p.is_reachout ? '<div class="reach-pill">Reach-Out List</div>' : ''}
          ${p.is_research_reachout ? '<div class="reach2-pill">Reach-Out List — Research</div>' : ''}
        </div>
        <p class="name">${p.name}</p>
        <p class="title">${p.title}</p>
        <p class="edu">${p.edu}</p>
        <div class="section-label">Research Interests</div>
        <ul>${p.research.map(r => `<li>${r}</li>`).join('')}</ul>
        ${p.classes.length ? `<div class="section-label">Classes Taught</div><ul>${p.classes.map(c => `<li>${c}</li>`).join('')}</ul>` : ''}
        ${p.org ? `<div class="section-label">Organization</div><div class="org-box">${p.org}</div>` : ''}
        ${p.course_match.length ? `<div class="section-label">Degree-Plan Course Match</div><ul>${p.course_match.map(c => `<li>${c}</li>`).join('')}</ul>` : ''}
        ${p.fall2026 ? `<div class="section-label">Fall 2026 Course</div><div class="fall-box">${p.fall2026}</div>` : ''}
        <div class="click-hint">${p.papers.length ? p.papers.length + ' research record(s) — click to view' : 'Click for full profile'}</div>
      </div>
    </div>
  `).join('');
}

function makeBtn(label, value, extraClass) {
  const btn = document.createElement('button');
  btn.textContent = label;
  if (extraClass) btn.classList.add(extraClass);
  if (value === active) btn.classList.add('active');
  btn.onclick = () => {
    active = value;
    document.querySelectorAll('.filters button').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    renderList();
  };
  return btn;
}

filtersEl.appendChild(makeBtn('Fall 2026 - Professor', 'Focus', 'focus-btn'));
filtersEl.appendChild(makeBtn('Reach-Out List', 'Reachout', 'reach-btn'));
filtersEl.appendChild(makeBtn('Reach-Out List — Research', 'ReachoutResearch', 'reach2-btn'));
const div = document.createElement('div');
div.className = 'divider';
filtersEl.appendChild(div);
['All', ...TIERS].forEach(t => filtersEl.appendChild(makeBtn(t === 'All' ? 'All' : t, t)));

renderList();

// ---------------- DETAIL VIEW ----------------
let paperFilterState = {};
let currentPerson = null;

function closeDetail() {
  detailEl.style.display = 'none';
  listViewEl.style.display = '';
  detailEl.style.removeProperty('--person-accent');
  window.scrollTo(0,0);
}

function openDetail(id) {
  currentPerson = PEOPLE.find(p => p.id === id);
  paperFilterState = { interest: new Set(), status: new Set(), year: new Set(), sector: new Set(), relevance: new Set(), access: new Set() };
  listViewEl.style.display = 'none';
  detailEl.style.display = 'block';
  const theme = (currentPerson.extra && currentPerson.extra.themeColor) ? currentPerson.extra.themeColor : '#0F6E56';
  detailEl.style.setProperty('--person-accent', theme);
  renderDetail();
  window.scrollTo(0,0);
}

function relPillClass(bucket) {
  if (bucket === 'High') return 'rel-high';
  if (bucket === 'Medium') return 'rel-medium';
  if (bucket === 'Low' || bucket === 'Low-Medium') return 'rel-low';
  return 'tbd';
}

function renderDetail() {
  const p = currentPerson;
  const extra = p.extra;

  let html = `<button class="back-btn" onclick="closeDetail()">&larr; Back to Directory</button>`;

  html += `<div class="detail-head">
    <img src="${p.photo || 'https://placehold.co/150x183/e2e0d8/6b6a63?text=' + encodeURIComponent(p.name.split(' ')[0])}" alt="${p.name}">
    <div>
      <div class="badges" style="margin-bottom:8px">
        <div class="tier-pill" style="background:${COLORS[p.tier]}">${p.tier}</div>
        ${p.is_advisor ? '<div class="advisor-pill">PhD Advisor</div>' : ''}
        ${p.is_focus ? '<div class="focus-pill">Fall 2026 - Professor</div>' : ''}
        ${p.is_reachout ? '<div class="reach-pill">Reach-Out List</div>' : ''}
        ${p.is_research_reachout ? '<div class="reach2-pill">Reach-Out List — Research</div>' : ''}
      </div>
      <h2>${p.name}</h2>
      <p class="dtitle">${p.title}</p>
      <p class="dtitle" style="color:var(--muted)">${p.edu}</p>
      ${extra ? `<div class="contact-row">${[extra.email, extra.phone, extra.room ? ('Room ' + extra.room) : null].filter(Boolean).join(' · ')}</div>` : ''}
      ${p.fall2026 ? `<div class="fall-box" style="display:inline-block;margin-top:10px">Fall 2026: ${p.fall2026}</div>` : ''}
    </div>
  </div>`;

  html += `<div class="detail-cols">
    <div class="detail-block">
      <h3>Research Interests</h3>
      <ul>${p.research.map(r => `<li>${r}</li>`).join('')}</ul>
    </div>
    <div class="detail-block">
      <h3>${p.classes.length ? 'Classes Taught' : (p.course_match.length ? 'Degree-Plan Course Match' : 'Organization')}</h3>
      ${p.classes.length ? `<ul>${p.classes.map(c => `<li>${c}</li>`).join('')}</ul>` : (p.course_match.length ? `<ul>${p.course_match.map(c => `<li>${c}</li>`).join('')}</ul>` : (p.org ? `<div class="org-box">${p.org}</div>` : '<p style="font-size:12.5px;color:var(--muted)">No public data yet.</p>'))}
    </div>`;

  if (extra) {
    html += `<div class="detail-block">
      <h3>Education</h3>
      <ul>${extra.education.map(e => `<li>${e}</li>`).join('')}</ul>
    </div>
    <div class="detail-block">
      <h3>Career Highlights</h3>
      <ul>${extra.career.map(e => `<li>${e}</li>`).join('')}</ul>
    </div>`;
  }

  html += `</div>`;

  if (p.papers.length) {
    html += renderResearchDB(p);
  }

  detailEl.innerHTML = html;
}

function uniqueValues(papers, getter) {
  const set = new Set();
  papers.forEach(pp => {
    const v = getter(pp);
    if (Array.isArray(v)) v.forEach(x => set.add(x));
    else set.add(v);
  });
  return Array.from(set);
}

function toggleFilter(cat, val) {
  if (paperFilterState[cat].has(val)) paperFilterState[cat].delete(val);
  else paperFilterState[cat].add(val);
  renderPaperList();
}

function clearFilters() {
  Object.keys(paperFilterState).forEach(k => paperFilterState[k].clear());
  renderPaperList();
}

function paperPasses(pp) {
  for (const cat of ['status','year','sector','relevance','access']) {
    const sel = paperFilterState[cat];
    if (sel.size === 0) continue;
    if (cat === 'status') {
      if (!pp.statusBucket.some(v => sel.has(v))) return false;
    } else {
      const bucketKey = cat === 'year' ? 'yearBucket' : cat === 'sector' ? 'sectorBucket' : cat === 'access' ? 'accessBucket' : 'relevanceBucket';
      if (!sel.has(pp[bucketKey])) return false;
    }
  }
  if (paperFilterState.interest.size > 0) {
    if (!pp.interest.some(v => paperFilterState.interest.has(v))) return false;
  }
  return true;
}

function renderPaperList() {
  const p = currentPerson;
  const list = p.papers.filter(paperPasses);
  document.getElementById('paperCount').textContent = list.length + ' of ' + p.papers.length + ' records';
  document.getElementById('paperList').innerHTML = list.map(pp => `
    <div class="paper-card">
      <div class="prow" onclick="togglePaper('${pp.id}')">
        <div>
          <p class="ptitle">${pp.id} — ${pp.title}</p>
          <p class="pmeta">${pp.year} &middot; ${pp.venue}</p>
          <div class="pill-row">
            ${pp.statusBucket.map(s => `<span class="pill ${s==='TBD'?'tbd':'status'}">${s}</span>`).join('')}
            <span class="pill sector">${pp.sectorBucket}</span>
            <span class="pill ${relPillClass(pp.relevanceBucket)}">Relevance: ${pp.relevanceBucket}</span>
            <span class="pill ${pp.isFree ? 'access-free' : (pp.accessBucket==='TBD' ? 'tbd' : 'access-pay')}">${pp.accessBucket}</span>
          </div>
          ${pp.crossLink ? `<div class="cross-badge">Network Link: ${pp.crossLink}</div>` : ''}
        </div>
      </div>
      <div class="link-row">${linkHtml(pp)}</div>
      <div class="paper-detail" id="pd-${pp.id}">
        ${pdRow('Co-authors', pp.coauthors)}
        ${pdRow('Interest Filter(s)', pp.interest.join('; '))}
        ${pdRow('Method/Technique', pp.method)}
        ${pdRow('Sector', pp.sector)}
        ${pdRow('Relevance to Lodging', pp.relevance)}
        ${pdRow('Data source', pp.datasource)}
        ${pdRow('Confidence', pp.confidence)}
        ${pdRow('Last verified', pp.verified)}
        ${pdRow('Access Type', pp.access)}
      </div>
    </div>
  `).join('') || '<p style="font-size:12.5px;color:var(--muted)">No records match this filter combination.</p>';
}

function linkHtml(pp) {
  if (!pp.hasLink) {
    return `<span class="link-none">${pp.link}</span>`;
  }
  if (pp.isFree) {
    return `<a class="link-free" href="${pp.link}" target="_blank" rel="noopener">Read now (free) &rarr;</a>`;
  }
  return `<a class="link-pay" href="${pp.link}" target="_blank" rel="noopener">View source (requires UH Library) &rarr;</a>`;
}

function pdRow(label, val) {
  const isTbd = /TBD|Not available/i.test(val);
  return `<div class="pd-row"><div class="pd-label">${label}</div><div class="pd-val ${isTbd?'tbd-val':''}">${val}</div></div>`;
}

function togglePaper(id) {
  const el = document.getElementById('pd-' + id);
  el.classList.toggle('open');
}

function renderResearchDB(p) {
  return `<div class="db-section">
    <h2>Research Database — ${p.name}</h2>
    <div class="db-note">
      "Sector" and "Relevance to Lodging" are custom fields. Fields marked <b>TBD</b> are unconfirmed placeholders.
    </div>
    <div class="filter-group"><div class="filter-group-label">Interest Filter</div><div class="chip-row" data-cat="interest"></div></div>
    <div class="filter-group"><div class="filter-group-label">Status</div><div class="chip-row" data-cat="status"></div></div>
    <div class="filter-group"><div class="filter-group-label">Year</div><div class="chip-row" data-cat="year"></div></div>
    <div class="filter-group"><div class="filter-group-label">Sector</div><div class="chip-row" data-cat="sector"></div></div>
    <div class="filter-group"><div class="filter-group-label">Relevance to Lodging</div><div class="chip-row" data-cat="relevance"></div></div>
    <div class="filter-group">
      <div class="filter-group-label">Access Type</div>
      <div class="chip-row" data-cat="access"></div>
      <button class="clear-btn" id="clearFiltersBtn">Clear all filters</button>
    </div>
    <div class="paper-count" id="paperCount"></div>
    <div id="paperList"></div>
  </div>`;
}

function buildChips(catData) {
  Object.keys(catData).forEach(cat => {
    const container = document.querySelector('.chip-row[data-cat="' + cat + '"]');
    if (!container) return;
    container.innerHTML = '';
    catData[cat].forEach(val => {
      const btn = document.createElement('button');
      btn.className = 'chip' + (val === 'TBD' ? ' tbd' : '');
      btn.textContent = val;
      btn.addEventListener('click', () => {
        btn.classList.toggle('active');
        toggleFilter(cat, val);
      });
      container.appendChild(btn);
    });
  });
  const clearBtn = document.getElementById('clearFiltersBtn');
  if (clearBtn) clearBtn.addEventListener('click', () => {
    clearFilters();
    document.querySelectorAll('.chip.active').forEach(c => c.classList.remove('active'));
  });
}

const _origRenderDetail = renderDetail;
renderDetail = function() {
  _origRenderDetail();
  if (currentPerson.papers.length) {
    const p = currentPerson;
    buildChips({
      interest: uniqueValues(p.papers, pp => pp.interest),
      status: uniqueValues(p.papers, pp => pp.statusBucket),
      year: uniqueValues(p.papers, pp => pp.yearBucket).sort(),
      sector: uniqueValues(p.papers, pp => pp.sectorBucket),
      relevance: ['High','Medium','Low-Medium','Low','TBD'].filter(r => uniqueValues(p.papers, pp => pp.relevanceBucket).includes(r)),
      access: uniqueValues(p.papers, pp => pp.accessBucket),
    });
    renderPaperList();
  }
};
